import{_ as s,o as l,c as t,a3 as i,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const h="/bilder/schueler/fhr-reiter.png",c="/bilder/schueler/fhr-leistungsdaten-und-berechnen.png",a="/bilder/schueler/fhr-ergebnis.png",w=JSON.parse('{"title":"Den schulischen Teil der Fachhochschulreife berechnen","description":"","frontmatter":{"title":"Den schulischen Teil der Fachhochschulreife berechnen","source_pageid":1110,"source_revision":4658},"headers":[],"relativePath":"schild3/schueler/fhr-schueler.md","filePath":"schild3/schueler/fhr-schueler.md"}'),d={name:"schild3/schueler/fhr-schueler.md"};function o(u,r,g,f,p,b){return l(),t("div",null,[...r[0]||(r[0]=[i('<h1 id="den-schulischen-teil-der-fachhochschulreife-berechnen" tabindex="-1">Den schulischen Teil der Fachhochschulreife berechnen <a class="header-anchor" href="#den-schulischen-teil-der-fachhochschulreife-berechnen" aria-label="Permalink to &quot;Den schulischen Teil der Fachhochschulreife berechnen&quot;">​</a></h1><p>Übernehmen Sie vorhandene Leistungsdaten der Qualifikationsphase und berechnen Sie den schulischen Teil der Fachhochschulreife. Beachten Sie den beschriebenen Sonderfall bei wiederholten Halbjahren.</p><p><a href="/bilder/schueler/fhr-reiter.png"><img src="'+h+'" alt="Anzeige des Reiters bei passend ausgewählter Schülermenge." loading="lazy"></a></p><p><em>Anzeige des Reiters bei passend ausgewählter Schülermenge.</em></p><p>Bei der Auswahl von Jahrgängen im Schülercontainer, in denen das Erreichen der Fachhochschulreife möglich ist, wird bei <em>Schüler</em> der zusätzliche Reiter <strong>FHR</strong> angezeigt.</p><p>Über diesen wird individuell berechnet, ob der <em>schulische Teil der Fachhochschulreife</em> erreicht wurde.</p><p><a href="/bilder/schueler/fhr-leistungsdaten-und-berechnen.png"><img src="'+c+'" alt="Leistungsdaten holen und den FHR berechnen." loading="lazy"></a></p><p><em>Leistungsdaten holen und den FHR berechnen.</em></p><p>Mit dem Schalter <strong>Leistungsdaten holen</strong> werden die Leistungsdaten, soweit schon vorliegend, der Q1 und Q2 geholt.</p><p>Für die gymnasiale Oberstufe nach <a href="https://bass.schule.nrw/9607.htm" target="_blank" rel="noreferrer">§ 40a APO-GOSt</a> werden die Halbjahre 1/2, 2/3 oder 3/4 der Qualifikationsphase betrachtet. Maßgeblich ist die schulrechtliche Folge; bei Wiederholungen sind nicht beliebige zwei gespeicherte Abschnitte kombinierbar. Beachten Sie die <a href="/zeugnisse/pruefungsordnungen.html">Zuordnung der Prüfungsordnung</a> und das unten beschriebene Wiederholungsproblem.</p><p>Über <strong>FHR-Algorithmus starten</strong> werden für das Erreichen des FHR und die Schnittoptimierung günstige zwei aufeinander folgende Halbjahre markiert und der FHR wird berechnet.<br> Hier blendet SchILD-NRW folgenden Hinweis ein:</p>',11),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[e("strong",null,"Ergebnis manuell prüfen:"),n(" In folgenden seltenen Fällen kann die automatische FHR-Berechnung fehlerhaft oder unvollständig sein:")]),e("ul",null,[e("li",null,"Die Q2 wird nach einer nicht bestandenen Abiturprüfung wiederholt und zuvor wurde bereits ein Halbjahr der Q2 wiederholt."),e("li",null,"Bei mehreren Fremdsprachen, Gesellschaftswissenschaften oder klassischen Naturwissenschaften unterscheiden sich die Halbjahresnoten sehr stark. Dann ermittelt SchILD-NRW 3 möglicherweise nicht die günstigste Punktzahl.")]),e("p",null,"Kontrollieren Sie in diesen Fällen den Berechnungsvorschlag von Hand.")],-1),i(`<p>Das folgende historische Protokollbeispiel zeigt eine frühere Prüfungsordnung; es legt nicht die für aktuelle Lernende zu wählende Prüfungsordnung fest:</p><pre><code> Altmann, Lena
 ========================================================================
 Prüfungsordnung: APO-GOSt(B)10/G8
 Schulischer Teil der Fachhochschulreife erreicht
</code></pre><p><a href="/bilder/schueler/fhr-ergebnis.png"><img src="`+a+'" alt="Das Ergebnis der Berechnung basierend auf den gewählten Halbjahren." loading="lazy"></a></p><p><em>Das Ergebnis der Berechnung basierend auf den gewählten Halbjahren.</em></p><p>Im unteren Bereich findet sich anschließend die Zusammenfassung.</p><p>Wurde ein Jahrgang angewählt, in dem der FHR berechnet werden kann, steht unter <em>Gruppenprozesse ➜ Allgemein</em> der Gruppenprozess <strong>Fachhochschulreife prüfen</strong> zur Verfügung, über den für die ganze Gruppe die Leistungsdaten geholt, markiert und geprüft werden.</p>',6),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Am beruflichen Gymnasium wird der "),e("strong",null,"schulische Teil der Fachhochschulreife"),n(" im Reiter "),e("strong",null,"FHR"),n(" geprüft. Er ist vom Erwerb der vollen Fachhochschulreife zu unterscheiden; siehe "),e("a",{href:"https://bass.schule.nrw/Inhalt/6911.htm",target:"_blank",rel:"noreferrer"},"Praktikum-Ausbildungsordnung, Abschnitt IV"),n(". Verfahren anderer BK-Bildungsgänge stehen unter "),e("strong",null,"BK-Abschluss"),n(". Der weitere Schulbesuch allein begründet keinen vollen FHR-Abschluss.")])],-1),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Die automatische Berechnung durch SchILD-NRW ist als Unterstützung ohne Gewähr zu verstehen. Die Verantwortung für die Korrektheit der Berechnungen trägt die Schule.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=FHR_(Sch%C3%BCler)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 4658.")],-1)])])}const k=s(d,[["render",o]]);export{w as __pageData,k as default};
